<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRouter, useRoute, onBeforeRouteLeave } from 'vue-router'
import { getSong, createSong, updateSong } from '../api'
import ConfirmLeave from './ConfirmLeave.vue'
const router = useRouter(), route = useRoute(), editing = computed(() => !!route.params.id)
const form = ref({ title:'', artist:'', album:'', year:new Date().getFullYear() }), original = ref(''), saving = ref(false), loading = ref(false), error = ref('')
const dirty = computed(() => original.value !== '' && JSON.stringify(form.value) !== original.value)
onMounted(async () => { if(editing.value) { loading.value = true; try { const song = await getSong(route.params.id); form.value = { title:song.title, artist:song.artist, album:song.album, year:song.year } } catch { error.value = 'Не вдалося завантажити композицію.' } finally { loading.value = false } } original.value = JSON.stringify(form.value) })
onBeforeRouteLeave(() => !dirty.value || window.confirm('Є незбережені зміни. Вийти без збереження?'))
async function save() { error.value = ''; if(!form.value.title.trim() || !form.value.artist.trim() || !form.value.album.trim() || !Number.isInteger(Number(form.value.year)) || Number(form.value.year) < 1900 || Number(form.value.year) > new Date().getFullYear()+1) { error.value = 'Заповніть усі поля. Рік має бути від 1900 до наступного року.'; return } saving.value = true; try { const data = { title:form.value.title.trim(), artist:form.value.artist.trim(), album:form.value.album.trim(), year:Number(form.value.year) }; if(editing.value) await updateSong(route.params.id, data); else await createSong(data); original.value = JSON.stringify(form.value); await router.push('/') } catch { error.value = 'Не вдалося зберегти композицію. Перевірте сервер.' } finally { saving.value = false } }
</script>
<template><ConfirmLeave :enabled="dirty"/><div class="form-layout"><div class="form-heading"><router-link to="/">← Повернутися до колекції</router-link><h1>{{ editing ? 'Редагувати композицію' : 'Нова композиція' }}</h1><p class="subtle">Заповніть інформацію про музичний запис.</p></div><form class="panel song-form" @submit.prevent="save"><p v-if="loading">Завантаження...</p><p v-if="error" class="error">{{ error }}</p><label>Назва композиції<input v-model="form.title" required maxlength="150" placeholder="Введіть назву" /></label><label>Виконавець<input v-model="form.artist" required maxlength="120" placeholder="Введіть виконавця" /></label><label>Альбом<input v-model="form.album" required maxlength="150" placeholder="Введіть альбом" /></label><label>Рік випуску<input v-model.number="form.year" type="number" min="1900" :max="new Date().getFullYear()+1" required /></label><p v-if="dirty" class="warning">● Є незбережені зміни</p><div class="actions"><router-link class="button secondary" to="/">Скасувати</router-link><button :disabled="saving || loading" type="submit">{{ saving ? 'Збереження...' : 'Зберегти композицію' }}</button></div></form></div></template>
